class Solution:
    def lengthOfLIS(self, nums: List[int], k: int) -> int:
        m = max(nums)
        size = 1
        while size < m + 1:
            size *= 2
        tree = [0] * (2 * size)

        def update(i, val):
            i += size
            tree[i] = max(tree[i], val)
            i //= 2
            while i:
                tree[i] = max(tree[2*i], tree[2*i+1])
                i //= 2

        def query(l, r):
            res = 0
            l += size; r += size + 1
            while l < r:
                if l & 1:
                    res = max(res, tree[l]); l += 1
                if r & 1:
                    r -= 1; res = max(res, tree[r])
                l //= 2; r //= 2
            return res

        ans = 1
        for v in nums:
            lo, hi = max(1, v - k), v - 1
            cur = query(lo, hi) + 1 if hi >= lo else 1
            update(v, cur)
            ans = max(ans, cur)
        return ans

