class Solution {
    private int[] tree;
    private int size;

    private void update(int i, int val) {
        i += size;
        tree[i] = Math.max(tree[i], val);
        for (i /= 2; i >= 1; i /= 2)
            tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
    }

    private int query(int l, int r) {
        int res = 0;
        for (l += size, r += size + 1; l < r; l /= 2, r /= 2) {
            if ((l & 1) == 1) res = Math.max(res, tree[l++]);
            if ((r & 1) == 1) res = Math.max(res, tree[--r]);
        }
        return res;
    }

    public int lengthOfLIS(int[] nums, int k) {
        int m = 0;
        for (int v : nums) m = Math.max(m, v);
        size = 1;
        while (size < m + 1) size *= 2;
        tree = new int[2 * size];
        int ans = 1;
        for (int v : nums) {
            int lo = Math.max(1, v - k), hi = v - 1;
            int cur = hi >= lo ? query(lo, hi) + 1 : 1;
            update(v, cur);
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

